using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.VTS.ReservacionesEstados;using GraphApi.Services.VTS.ReservacionesEstados;namespace GraphApi.Controllers.VTS.ReservacionesEstados{    /// <summary>    /// Gestión de ReservacionesEstados: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("VTS/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre ReservacionesEstados")]    public class ReservacionesEstadosController : Controller    {        private readonly IReservacionesEstadosService _objService;        public ReservacionesEstadosController(IReservacionesEstadosService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los ReservacionesEstados, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="reservacionEstadoID">ReservacionEstadoID</param>        /// <param name="reservacionEstado">ReservacionEstado</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de ReservacionesEstados</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar ReservacionesEstados",            Description = "Devuelve ReservacionesEstados aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadReservacionesEstados>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadReservacionesEstados>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? reservacionEstadoID,            [FromQuery] string? reservacionEstado,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetReservacionesEstadosDynamic(                reservacionEstadoID,                 reservacionEstado,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo ReservacionesEstado.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del ReservacionesEstado a crear.</param>        /// <returns>El ReservacionesEstado recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear ReservacionesEstados",            Description = "Inserta un nuevo ReservacionesEstado en la base de datos."        )]        [ProducesResponseType(typeof(clReadReservacionesEstados), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadReservacionesEstados>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateReservacionesEstados objInput)        {            var vCreated = await _objService.CreateReservacionesEstados(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de ReservacionesEstado.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del ReservacionesEstado.</param>        /// <returns>El ReservacionesEstado actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar ReservacionesEstados",            Description = "Actualiza uno o varios campos de ReservacionesEstado existente."        )]        [ProducesResponseType(typeof(clReadReservacionesEstados), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadReservacionesEstados>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateReservacionesEstados objInput)        {            var vUpdated = await _objService.UpdateReservacionesEstados(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un ReservacionesEstado por su ID.        /// </summary>        [HttpDelete("{nReservacionesEstadosID:int}")]        [SwaggerOperation(            Summary = "Eliminar ReservacionesEstado",            Description = "Borra un ReservacionesEstado si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nReservacionesEstadosID)        {            var success = await _objService.DeleteReservacionesEstados(nReservacionesEstadosID);            return success ? NoContent() : NotFound();        }    }}